package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Fraction.compareTo(Fraction)
 */
public class Fraction_compareTo_TriageGen4Test {







    @Test
    public void testCompareTo_NegativeValues() {
        // Testing negative logic coverage
        Fraction f1 = new Fraction(-1, 2); // -0.5
        Fraction f2 = new Fraction(1, 2);  // 0.5
        assertEquals(-1, f1.compareTo(f2));

        Fraction f3 = new Fraction(-1, 2); // -0.5
        Fraction f4 = new Fraction(-1, 4); // -0.25
        assertEquals(-1, f3.compareTo(f4));

        Fraction f5 = new Fraction(-1, 4); // -0.25
        Fraction f6 = new Fraction(-1, 2); // -0.5
        assertEquals(1, f5.compareTo(f6));
    }


}

package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for Fraction.compareTo(Fraction)
 */
public class Fraction_compareTo_TriageGen4Test {









    @Test
    public void testCompareTo_Zero() {
        Fraction zero = new Fraction(0, 1);
        Fraction positive = new Fraction(5, 1);
        Fraction negative = new Fraction(-5, 1);

        assertEquals(-1, zero.compareTo(positive));
        assertEquals(1, zero.compareTo(negative));
        assertEquals(0, zero.compareTo(zero));
    }
}
